// The page and the assistant side by side, as the web draws them; on a width that cannot hold both, the
// assistant sits under the page.
ViewThatFits(in: .horizontal) {
    HStack(alignment: .top, spacing: theme.spacing.space3) {
        page.frame(maxWidth: .infinity, alignment: .topLeading)
        if isAssistantOpen {
            panel.frame(width: 250)
        } else {
            MonarchAiLauncher(isOpen: $isAssistantOpen)
        }
    }
    .frame(minWidth: 520, minHeight: 560, alignment: .top)
    VStack(alignment: .leading, spacing: theme.spacing.space3) {
        page
        if isAssistantOpen {
            panel.frame(height: 540)
        } else {
            MonarchAiLauncher(isOpen: $isAssistantOpen)
        }
    }
}
.padding(theme.spacing.space3)
.overlay(RoundedRectangle(cornerRadius: theme.radius.lg, style: .continuous).stroke(theme.colors.borderSubtle))
.onChange(of: selected, initial: true) { _, selection in
    conversation.body = requestBody(for: selection)
}
.dynamicTypeSize(.xSmall)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme

private struct EchoTransport: MonarchAiTransport {
    func stream(_ request: MonarchAiTransportRequest) -> MonarchAiEventStream {
        MonarchAiEventStream { continuation in
            continuation.yield(.textDelta("You asked: " + (request.messages.last?.text ?? "")))
            continuation.yield(.done())
            continuation.finish()
        }
    }
}

private let rows = [{{rows.0}}, {{rows.1}}, {{rows.2}}, {{rows.3}}]

// Hold the conversation above the navigation so it survives moving between screens.
@State private var conversation = MonarchAiConversation(transport: EchoTransport())
@State private var isAssistantOpen = {{assistant.open}}
@State private var draft = ""
// The page owns the selection; the recipe shows it as a chip and sends it with the next prompt.
@State private var selected: [String] = []

private var page: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space3) {
        Text({{heading}})
            .monarchTextStyle(.subheading)
            .foregroundStyle(theme.colors.textDefault)
            .accessibilityAddTraits(.isHeader)
        Text({{description}})
            .monarchTextStyle(.caption)
            .foregroundStyle(theme.colors.textMuted)
        ForEach(rows, id: \.self) { row in
            Toggle(row, isOn: isSelected(row))
                .toggleStyle(.monarchCheckbox)
        }
    }
}

private var panel: some View {
    MonarchAiAssistantPanel(
            {{assistant.title}},
            conversation: conversation,
            isPresented: $isAssistantOpen,
            prompt: $draft,
            context: context,
            starters: [
                MonarchAiStarterPrompt(id: "sum", title: {{assistant.starters.0}}, prompt: {{assistant.starters.0}}),
                MonarchAiStarterPrompt(id: "risk", title: {{assistant.starters.1}}, prompt: {{assistant.starters.1}}),
            ],
            onRemoveContext: { id in if id == "selection" { selected = [] } },
            headerActions: {},
            toolbar: {},
            footer: {}
        )
        .overlay(RoundedRectangle(cornerRadius: theme.radius.lg, style: .continuous).stroke(theme.colors.borderSubtle))
        .clipShape(RoundedRectangle(cornerRadius: theme.radius.lg, style: .continuous))
}

private var context: [MonarchAiContextItem] {
    var items = [MonarchAiContextItem(id: "page", kind: .page, label: {{assistant.context}}, isRemovable: false, group: "Page")]
    if !selected.isEmpty {
        items.append(
            MonarchAiContextItem(
                id: "selection",
                kind: .selection,
                label: selected.count == 1 ? "1 row" : "\(selected.count) rows",
                description: selected.joined(separator: "; ")
            )
        )
    }
    return items
}

private func isSelected(_ row: String) -> Binding<Bool> {
    Binding(
        get: { selected.contains(row) },
        set: { isOn in selected = rows.filter { $0 == row ? isOn : selected.contains($0) } }
    )
}

// The selection as label and text objects under the selection request field.
private func requestBody(for selection: [String]) -> [String: MonarchAiJSON] {
    guard !selection.isEmpty else { return [:] }
    return ["selection": .array([.object(["label": .string("Selected"), "text": .string(selection.joined(separator: "; "))])])]
}

